record.field:
[
  {
    "key": "latest_update",
    "type": "long_text",
    "label": "Latest Update — apa yang berubah sejak update terakhir?",
    "required": true
  },
  {
    "key": "next_action",
    "type": "long_text",
    "label": "Next Action — langkah berikutnya apa?",
    "required": true
  },
  {
    "key": "next_due",
    "type": "date",
    "label": "Due Date — kapan?",
    "required": true
  },
  {
    "key": "owner",
    "type": "user_ref",
    "label": "PIC",
    "required": false
  },
  {
    "key": "hanging_reason",
    "type": "cause_code",
    "label": "Kalau belum bergerak, kenapa?",
    "options": [
      {
        "code": "menunggu_approval",
        "class": "process",
        "label": "Menunggu approval"
      },
      {
        "code": "menunggu_pihak_luar",
        "class": "external",
        "label": "Menunggu pihak luar / klien"
      },
      {
        "code": "menunggu_dependency",
        "class": "process",
        "label": "Menunggu pekerjaan lain"
      },
      {
        "code": "kurang_waktu",
        "class": "resource",
        "label": "Tidak sempat dikerjakan"
      },
      {
        "code": "kurang_info",
        "class": "process",
        "label": "Kurang informasi / brief"
      },
      {
        "code": "teknis",
        "class": "resource",
        "label": "Kendala teknis"
      },
      {
        "code": "lainnya",
        "class": "external",
        "label": "Lainnya"
      }
    ],
    "show_when": {
      "question": "latest_update",
      "op": "unchanged_from_previous"
    },
    "require_detail_when": [
      "lainnya"
    ]
  }
]

[
  {
    "key": "channels",
    "type": "checklist",
    "label": "Channel yang dicek",
    "repeat_over": "enrolment.channels",
    "fields": [
      {
        "key": "checked",
        "type": "boolean",
        "label": "Sudah dicek?"
      },
      {
        "key": "total_open",
        "type": "number",
        "label": "Total aktif/open"
      },
      {
        "key": "hanging_gt3",
        "type": "number",
        "label": "Gantung >3 hari"
      },
      {
        "key": "hanging_lt3",
        "type": "number",
        "label": "Gantung <3 hari"
      },
      {
        "key": "replied",
        "type": "number",
        "label": "Sudah dibalas"
      }
    ]
  },
  {
    "key": "still_hanging",
    "type": "number",
    "label": "Total masih gantung",
    "computed": "sum(channels.hanging_gt3) + sum(channels.hanging_lt3)",
    "help": "Dihitung sistem. Tidak bisa lapor 13 open, 0 gantung, 2 gantung >3 hari."
  },
  {
    "key": "unresolved",
    "type": "thread_list",
    "label": "Yang belum selesai — jadikan apa?",
    "convertible_to": [
      "approval",
      "signature",
      "schedule",
      "task",
      "project"
    ],
    "help": "Thread gantung harus jadi objek yang dilacak, atau ditutup dengan alasan. Tidak bisa cuma hilang."
  },
  {
    "key": "escalation",
    "type": "long_text",
    "label": "Kendala/insight yang perlu dieskalasi",
    "required": false
  },
  {
    "key": "next_action",
    "type": "long_text",
    "label": "Next action untuk yang masih gantung",
    "required": false
  },
  {
    "key": "next_due",
    "type": "date",
    "label": "Kapan?",
    "required": false
  }
]

[
  {
    "key": "latest_update",
    "type": "long_text",
    "label": "Terakhir gimana?",
    "required": true
  },
  {
    "key": "stage",
    "type": "stage",
    "label": "Sekarang di tahap mana?",
    "stages": [
      "contacted",
      "qualified",
      "proposal",
      "negotiation",
      "won",
      "lost"
    ],
    "required": true
  },
  {
    "key": "next_action",
    "type": "long_text",
    "label": "Next action apa?",
    "required": true
  },
  {
    "key": "next_due",
    "type": "date",
    "label": "Kapan?",
    "required": true
  },
  {
    "key": "owner",
    "type": "user_ref",
    "label": "Siapa PIC-nya?",
    "required": false
  },
  {
    "key": "stall_reason",
    "type": "cause_code",
    "label": "Kalau belum bergerak, kenapa?",
    "options": [
      {
        "code": "menunggu_approval_internal",
        "class": "process",
        "label": "Menunggu approval internal"
      },
      {
        "code": "customer_diam",
        "class": "external",
        "label": "Customer belum merespons"
      },
      {
        "code": "harga",
        "class": "strategy",
        "label": "Harga belum cocok"
      },
      {
        "code": "butuh_spek",
        "class": "process",
        "label": "Menunggu spesifikasi / proposal"
      },
      {
        "code": "budget_klien",
        "class": "external",
        "label": "Budget klien belum turun"
      },
      {
        "code": "belum_paham_produk",
        "class": "capability",
        "label": "Perlu dukungan menjelaskan produk"
      },
      {
        "code": "lainnya",
        "class": "external",
        "label": "Lainnya"
      }
    ],
    "show_when": {
      "question": "stage",
      "op": "unchanged_from_previous"
    },
    "require_detail_when": [
      "lainnya"
    ]
  }
]

[
  {
    "key": "prista_blocker",
    "type": "long_text",
    "label": "Dari project yang masih gantung, mana yang paling mengkhawatirkan dan kenapa?",
    "required": true,
    "prefill_context": "prista_summary"
  },
  {
    "key": "root_fix",
    "type": "long_text",
    "label": "Root fix — apa yang harus berubah supaya ini tidak terulang?",
    "required": true,
    "help": "Fruit fix (menyelesaikan yang ini) sudah tercatat sebagai commitment di PRISTA. Yang ditanya di sini yang sistemik."
  },
  {
    "key": "latin_missed_reason",
    "type": "long_text",
    "label": "LATIN yang terlewat hari ini — kenapa?",
    "required": false,
    "show_when": {
      "question": "$computed.latin_missed",
      "op": "gt",
      "value": 0
    }
  },
  {
    "key": "tomorrow",
    "type": "long_text",
    "label": "Besok fokus ke apa?",
    "required": true
  },
  {
    "key": "next_due",
    "type": "date",
    "label": "Target kapan selesai?",
    "required": false
  }
]
